                motif_groups.setdefault(frozenset((r-r0,c-c0) for r,c in cells), []).append((color,cells))
        repeated = [g for g in motif_groups.values() if len(g)>1]
        if repeated:
            group=max(repeated,key=lambda g:len(g[0][1]))
            target=max(group,key=lambda x:max(r for r,c in x[1]))[1]
            # Recolor the later duplicate with the earlier duplicate's color.
            replacement = min(group, key=lambda x:min(r for r,c in x[1]))[0]
            for r,c in target: out[r][c]=replacement
            return out

        rdir = 1 if any(r < cr and (r,cc) in guide for r in range(cr)) else -1
        cdir = 1 if any(c < cc and (cr,c) in guide for c in range(cc)) else -1
        candidates=[]
        for color,cells in comps:
            if cells==guide: continue
            rs=[r for r,c in cells]; cs=[c for r,c in cells]
            # A candidate must lie wholly in the diagonal sector, not merely
            # have its centroid there (which admits objects touching the corner).
            row_ok = max(rs) < cr if rdir < 0 else min(rs) > cr
            col_ok = max(cs) < cc if cdir < 0 else min(cs) > cc
            if row_ok and col_ok:
                cy=sum(r for r,c in cells)/len(cells); cx=sum(c for r,c in cells)/len(cells)
                candidates.append((-(abs(cy-cr)+abs(cx-cc)),len(cells),cells))
        if candidates:
            target=min(candidates,key=lambda x:(x[0],x[1]))[2]
            for r,c in target: out[r][c]=gc
    return out

